from ..interactions import dashboard
from ..interactions import rtp_import

class RTPImport():
    def __init__(self) -> None:
        pass

    def import_first_plan(self):
        dashboard.open_rtp_import()
        rtp_import.click_rtp_import_select_button()
        rtp_import.click_tree_item_treatment_fields()
        rtp_import.click_promote_plan_field_groups_button()
        rtp_import.select_first_site_name_in_edit_fields_dialog()
        rtp_import.select_clinical_tolerance_in_edit_fields_dialog()
        rtp_import.click_edit_in_fields_OK_button()
        rtp_import.click_promote_plan_promote_button()
        rtp_import.click_no_button_in_delete_move_dialog()
        rtp_import.click_rtp_import_close_button()